use mcrf_bs_routing_policy::{service_nat::{Nat,Error},service_flows::{Registry,Key},packet::PacketInfo,packet_nat};
mod support;use support::*;
fn endpoints(bytes:&[u8])->Key{let p=PacketInfo::read(bytes).unwrap();let(a,b)=p.ports.unwrap();Key{protocol:p.protocol,local_port:a,peer:std::net::SocketAddr::new(p.destination,b)}}
fn state(capacity:usize)->Nat{Nat::new(42,&["10.89.0.2".parse().unwrap(),"fd00::2".parse().unwrap()],&["192.0.2.7".parse().unwrap(),"2001:db8::7".parse().unwrap()],capacity).unwrap()}
#[test]fn dual_stack_tcp_udp_translation_keeps_exact_payload_and_checksums(){
 for v6 in [false,true]{for tcp in [false,true]{let original=packet(v6,tcp);let key=endpoints(&original);let mut registry=Registry::scoped(42,10001).unwrap();registry.register_scoped(42,0,1,key).unwrap();let proof=registry.authorize(42,0,Some(10001),key).unwrap().unwrap();let mut nat=state(8);let mut wire=original.clone();let pointer=wire.as_ptr();
  nat.outbound(42,0,proof,&mut wire,|p|registry.current(42,0,p).unwrap()).unwrap();assert_eq!(wire.as_ptr(),pointer);let info=PacketInfo::read(&wire).unwrap();assert_ne!(info.ports.unwrap().0,key.local_port);assert_eq!(info.source,if v6{"2001:db8::7"}else{"192.0.2.7"}.parse::<std::net::IpAddr>().unwrap());let at=if v6{40}else{20};assert_eq!(checksum(&pseudo(&wire,at)),0);if !v6{assert_eq!(checksum(&wire[..20]),0)}
  let original_info=PacketInfo::read(&original).unwrap();let expected=packet_nat::rewrite(&original,key.peer.ip(),original_info.source,Some((key.peer.port(),key.local_port))).unwrap();
  let mut reply=packet_nat::rewrite(&wire,key.peer.ip(),info.source,Some((key.peer.port(),info.ports.unwrap().0))).unwrap();assert_eq!(nat.incoming(42,1,&mut reply,|p|registry.current(42,1,p).unwrap()),Ok(Some(proof)));assert_eq!(reply,expected);assert_eq!(checksum(&pseudo(&reply,at)),0);
 }}
}
#[test]fn revoked_lease_and_reused_socket_port_cannot_inherit_delayed_reply(){
 let original=packet(false,false);let key=endpoints(&original);let mut registry=Registry::scoped(42,10001).unwrap();registry.register_scoped(42,0,1,key).unwrap();let proof=registry.authorize(42,0,Some(10001),key).unwrap().unwrap();let mut nat=state(1);let mut wire=original.clone();nat.outbound(42,0,proof,&mut wire,|p|registry.current(42,0,p).unwrap()).unwrap();let info=PacketInfo::read(&wire).unwrap();let port=info.ports.unwrap().0;let old_reply=packet_nat::rewrite(&wire,key.peer.ip(),info.source,Some((key.peer.port(),port))).unwrap();
 registry.unregister(42,1,1).unwrap();let mut retired=old_reply.clone();assert_eq!(nat.incoming(42,1,&mut retired,|p|registry.current(42,1,p).unwrap()),Ok(None));assert_eq!(retired,old_reply);
 registry.register_scoped(42,2,2,key).unwrap();let next=registry.authorize(42,2,Some(10001),key).unwrap().unwrap();let mut newer=original.clone();nat.outbound(42,2,next,&mut newer,|p|registry.current(42,2,p).unwrap()).unwrap();assert_ne!(PacketInfo::read(&newer).unwrap().ports.unwrap().0,port);assert_eq!(nat.incoming(42,3,&mut retired,|p|registry.current(42,3,p).unwrap()),Ok(None));assert_eq!(retired,old_reply);
}
#[test]fn tuple_owner_generation_source_and_peer_must_match(){
 let original=packet(false,false);let key=endpoints(&original);let mut registry=Registry::scoped(42,10001).unwrap();registry.register_scoped(42,0,1,key).unwrap();assert!(registry.authorize(42,0,Some(10002),key).unwrap().is_none());let proof=registry.authorize(42,0,Some(10001),key).unwrap().unwrap();let mut nat=state(2);
 let mut denied=original.clone();assert_eq!(nat.outbound(42,0,proof,&mut denied,|_|false),Err(Error::Denied));assert_eq!(denied,original);assert_eq!(nat.outbound(43,0,proof,&mut denied,|_|true),Err(Error::Generation));assert_eq!(denied,original);
 let mut altered=packet_nat::rewrite(&original,"10.89.0.3".parse().unwrap(),key.peer.ip(),Some((key.local_port,key.peer.port()))).unwrap();let before=altered.clone();assert_eq!(nat.outbound(42,0,proof,&mut altered,|p|registry.current(42,0,p).unwrap()),Err(Error::Identity));assert_eq!(altered,before);
 nat.outbound(42,0,proof,&mut denied,|p|registry.current(42,0,p).unwrap()).unwrap();let info=PacketInfo::read(&denied).unwrap();let mut spoof=packet_nat::rewrite(&denied,"192.0.2.99".parse().unwrap(),info.source,Some((key.peer.port(),info.ports.unwrap().0))).unwrap();let before=spoof.clone();assert_eq!(nat.incoming(42,1,&mut spoof,|p|registry.current(42,1,p).unwrap()),Ok(None));assert_eq!(spoof,before);
}
#[test]fn control_and_native_lease_namespaces_cannot_alias(){
 let original=packet(false,true);let key=endpoints(&original);let mut control=Registry::new(42,10001).unwrap();let mut native=Registry::scoped(42,10001).unwrap();control.register(42,0,1,key,30000).unwrap();native.register_scoped(42,0,1,key).unwrap();let a=control.authorize(42,0,Some(10001),key).unwrap().unwrap();let b=native.authorize(42,0,Some(10001),key).unwrap().unwrap();assert_ne!(a,b);assert!(!control.current(42,0,&b).unwrap());assert!(!native.current(42,0,&a).unwrap());
 let mut nat=state(2);let mut first=original.clone();let mut second=original.clone();nat.outbound(42,0,a,&mut first,|p|control.current(42,0,p).unwrap()||native.current(42,0,p).unwrap()).unwrap();nat.outbound(42,0,b,&mut second,|p|control.current(42,0,p).unwrap()||native.current(42,0,p).unwrap()).unwrap();assert_ne!(PacketInfo::read(&first).unwrap().ports,PacketInfo::read(&second).unwrap().ports);
}
#[test]fn capacity_never_evicts_live_flow_and_close_denies_all(){
 let original=packet(false,false);let key=endpoints(&original);let mut registry=Registry::scoped(42,10001).unwrap();registry.register_scoped(42,0,1,key).unwrap();let a=registry.authorize(42,0,Some(10001),key).unwrap().unwrap();let mut nat=state(1);let mut first=original.clone();nat.outbound(42,0,a,&mut first,|p|registry.current(42,0,p).unwrap()).unwrap();let stable=first.clone();
 let mut second=packet_nat::rewrite(&original,"10.89.0.2".parse().unwrap(),key.peer.ip(),Some((41235,key.peer.port()))).unwrap();let bkey=endpoints(&second);registry.register_scoped(42,1,2,bkey).unwrap();let b=registry.authorize(42,1,Some(10001),bkey).unwrap().unwrap();let before=second.clone();assert_eq!(nat.outbound(42,1,b,&mut second,|p|registry.current(42,1,p).unwrap()),Err(Error::Capacity));assert_eq!(second,before);
 first=original.clone();nat.outbound(42,2,a,&mut first,|p|registry.current(42,2,p).unwrap()).unwrap();assert_eq!(first,stable);nat.close();let mut bytes=original.clone();assert_eq!(nat.outbound(42,3,a,&mut bytes,|_|true),Err(Error::Closed));assert_eq!(bytes,original);
}
